function html(){if(!E())return '<section class="panel section-gap"><h2>模型解释</h2><p>解释数据尚未载入。</p></section>';return `<section class="panel section-gap explain-section"><div class="split-head"><div><div class="eyebrow">EXTERNAL COHORT · MODEL INSIGHTS</div><h2>哪些指标影响了预测？模型参考了谁？</h2></div><span class="badge">I-SPY 1 · 38例</span></div><p class="small muted">SHAP把预测拆成各项指标的贡献：蓝色表示相对参考值推高概率，橙色表示拉低概率。</p><div class="explain-tabs" role="tablist" aria-label="模型解释视图">${[['local','这位患者 · SHAP'],['global','所有患者 · SHAP'],['flow','注意力怎样工作'],['attention','注意力矩阵']].map(([id,label])=>`<button role="tab" aria-selected="${view===id}" data-explain-view="${id}">${label}</button>`).join('')}</div><div id="explain-content"></div><details><summary>计算方法与数据</summary><div class="detail-content"><p>SHAP：十折原始概率均值；保持患者连线和其他患者的输入不变，将当前患者与外部队列特征中位数参考比较。采用PermutationExplainer，32组正反向排列。参考概率 + 全部SHAP贡献 = 当前患者概率。</p><p>注意力：最后一层跨模型关注了谁，行是查询患者，列是被关注患者。它展示模型关注分布；SHAP则展示输入相对参考值的贡献。</p><a href="explain-data.json" download>下载外部解释数据 ↗</a></div></details></section>`;}
function content(){const e=E(),p=D().patients[current];if(view==='flow')return window.RespAttentionFlow.html(current);if(view==='local')return `<div class="explain-metrics"><div><span>换成参考指标时的预测</span><b>${pct(e.base_values[current])}</b></div><div><span>这些指标带来的变化</span><b>${pp(e.shap_values[current].reduce((a,b)=>a+b,0))}</b></div><div><span>${p.id} · 原始概率</span><b>${pct(p.p)}</b></div></div><div class="explain-grid"><div><h3>各项指标怎样改变预测</h3><div class="chart-key"><span><i class="swatch"></i>推动概率上升</span><span><i class="swatch orange"></i>推动概率下降</span></div><div class="explain-scroll"><svg id="shap-waterfall" aria-label="当前患者SHAP贡献瀑布图" role="img"></svg></div></div><div>${importance()}</div></div>`;
if(view==='global')return `<div class="explain-grid"><div><h3>38位患者的 SHAP 分布</h3><p class="small">每个点是一位患者，点击切换到她的响应信息。</p><div class="chart-key"><span>特征值低 <i class="feature-gradient"></i> 高</span><span>描边：${p.id}</span></div><div class="explain-scroll"><svg id="shap-beeswarm" role="img" aria-label="外部患者SHAP分布，颜色表示输入特征值"></svg></div></div><div>${importance()}</div></div>`;
const m=matrix(),row=m[current],sorted=row.map((v,i)=>({v,i})).sort((a,b)=>b.v-a.v),entropy=-row.reduce((s,v)=>s+(v>0?v*Math.log(v):0),0)/Math.log(row.length),minimum=Math.min(...row),maximum=Math.max(...row);
return `<div class="attention-row-focus"><h3>${p.id} · 当前患者的关注权重</h3><div class="attention-row-strip">${row.map((v,i)=>`<button class="${sorted.slice(0,5).some(n=>n.i===i)?'top':''} ${i===current?'query':''}" data-attention-patient="${i}" title="${p.id} → ${D().patients[i].id} · ${fmt(v*100,4)}%" aria-label="查看${D().patients[i].id}，关注权重${fmt(v*100,4)}%"><i style="height:${v/maximum*70}px"></i><small>${i%5===0||i===37?String(i+1).padStart(3,'0'):''}</small></button>`).join('')}</div><p>条高按实际权重比例显示 · 浅色为前5位 · 悬停查看数值</p></div><div class="toolbar"><label>模型 <select id="attention-model"><option value="-1">十折与各头平均</option>${Array.from({length:e.attention.model_count||e.attention.models.length},(_,i)=>`<option value="${i}" ${model===i?'selected':''}>模型 ${i+1}</option>`).join('')}</select></label><label>注意力头 <select id="attention-head" ${model<0?'disabled':''}><option value="-1">各头平均</option>${Array.from({length:e.attention.head_count||e.attention.models[0].length},(_,i)=>`<option value="${i}" ${head===i?'selected':''}>Head ${i+1}</option>`).join('')}</select></label></div><div class="attention-layout"><div><h3>患者 → 患者 · 关注权重</h3><p class="small">行：查询患者 / 列：被关注患者 · 点击行切换患者</p><div class="attention-canvas-wrap"><canvas id="attention-matrix" role="img" aria-label="38乘38模型关注了谁矩阵"></canvas><div id="attention-tip" class="attention-tip" role="status">${p.id} 的关注分布已高亮</div></div><div class="small muted">颜色：0 → 当前视图最大值 ${fmt(Math.max(...m.flat())*100,4)}% · 均匀参考 ${fmt(100/38,4)}%</div></div><div><div class="explain-metrics compact"><div><span>关注分布的均匀程度</span><b>${fmt(entropy,4)}</b></div><div><span>这位患者的关注权重范围</span><b class="small-number">${fmt(minimum*100,4)}–${fmt(maximum*100,4)}%</b></div></div><h3>${p.id} 最关注的患者</h3>${sorted.slice(0,8).map(({v,i})=>`<button class="attention-neighbor" data-attention-patient="${i}"><span>${D().patients[i].id}${i===current?' · 自身':''}</span><b>${fmt(v*100,4)}%</b></button>`).join('')}<div class="small muted section-gap">权重占比 · 熵接近1表示关注较均匀</div></div></div>`;}
function waterfall(){const e=E(),phi=e.shap_values[current],order=phi.map((_,i)=>i).sort((a,b)=>Math.abs(phi[b])-Math.abs(phi[a]));const rows=order.slice(0,8).map(f=>({name:name(e.features[f]),v:phi[f],value:e.feature_values[current][f]}));if(order.length>8)rows.push({name:'其余 '+(order.length-8)+' 项',v:order.slice(8).reduce((s,i)=>s+phi[i],0)});let running=e.base_values[current],extents=[running];rows.forEach(r=>{r.start=running;running+=r.v;r.end=running;extents.push(running);});const lo=Math.min(...extents),hi=Math.max(...extents),pad=Math.max(.01,(hi-lo)*.18),min=lo-pad,max=hi+pad,W=690,H=rows.length*43+90,L=190,R=80,X=v=>L+(v-min)/(max-min)*(W-L-R);let out='';for(let i=0;i<5;i++){const v=min+(max-min)*i/4,x=X(v);out+=`<path d="M${x},20 V${H-40}" stroke="#254457" stroke-dasharray="3 4"/><text x="${x}" y="${H-14}" text-anchor="middle">${pct(v)}</text>`;}rows.forEach((r,i)=>{const y=33+i*43,a=X(r.start),b=X(r.end),color=r.v>=0?'#43a5ff':'#f2994a';out+=`<text x="${L-12}" y="${y+5}" text-anchor="end">${r.name}</text><rect x="${Math.min(a,b)}" y="${y-10}" width="${Math.max(1,Math.abs(a-b))}" height="22" rx="3" fill="${color}"><title>${r.name}: ${pp(r.v)}${r.value===undefined?'':' · 输入 '+fmt(r.value,4)}</title></rect><text x="${W-5}" y="${y+5}" text-anchor="end">${pp(r.v)}</text>${i<rows.length-1?`<path d="M${b},${y+12} V${y+33}" stroke="#8096a8" stroke-dasharray="3 3"/>`:''}`;});const svg=$('#shap-waterfall');svg.setAttribute('viewBox',`0 0 ${W} ${H}`);svg.innerHTML=out;}
function beeswarm(){const e=E(),order=ranking().slice(0,8),W=690,H=480,L=190,R=35,max=Math.max(...e.shap_values.flat().map(Math.abs))||.01,X=v=>L+(v/max+1)/2*(W-L-R);let out=`<path d="M${X(0)},10 V425" stroke="#7792a8"/>`;for(let t=-2;t<=2;t++){const v=max*t/2;out+=`<text x="${X(v)}" y="451" text-anchor="middle">${fmt(v*100,1)}</text>`;}out+='<text x="430" y="476" text-anchor="middle">SHAP值（概率百分点）</text>';order.forEach((f,j)=>{const y=35+j*51,vals=e.feature_values.map(r=>r[f]),lo=Math.min(...vals),hi=Math.max(...vals),occupied=[];out+=`<text x="${L-12}" y="${y+4}" text-anchor="end">${name(e.features[f])}</text><path d="M${L},${y} H${W-R}" stroke="#21394b"/>`;e.shap_values.forEach((row,i)=>{const x=X(row[f]);let dy=0;for(let k=0;k<9;k++){const candidate=k===0?0:Math.ceil(k/2)*5*(k%2?1:-1);if(!occupied.some(p=>Math.hypot(p[0]-x,p[1]-candidate)<5.4)){dy=candidate;break;}}occupied.push([x,dy]);const t=(vals[i]-lo)/Math.max(1e-10,hi-lo),rgb=[242+(67-242)*t,153+(165-153)*t,74+(255-74)*t].map(Math.round);out+=`<circle data-shap-patient="${i}" tabindex="0" role="button" aria-label="${D().patients[i].id} ${name(e.features[f])} ${pp(row[f])}" cx="${x}" cy="${y+dy}" r="${i===current?4.5:3.2}" fill="rgb(${rgb})" stroke="${i===current?'white':'none'}"><title>${D().patients[i].id} · 输入 ${fmt(vals[i],4)} · SHAP ${pp(row[f])}</title></circle>`;});});const svg=$('#shap-beeswarm');svg.setAttribute('viewBox',`0 0 ${W} ${H}`);svg.innerHTML=out;svg.querySelectorAll('[data-shap-patient]').forEach(c=>{const pick=()=>callback(Number(c.dataset.shapPatient));c.onclick=pick;c.onkeydown=event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();pick();}};});}
function attentionCanvas(){const c=$('#attention-matrix');if(!c)return;const w=Math.max(280,c.clientWidth),h=w,dpr=Math.min(devicePixelRatio||1,2);c.width=w*dpr;c.height=h*dpr;const ctx=c.getContext('2d');ctx.scale(dpr,dpr);const m=matrix(),max=Math.max(...m.flat()),pad=35,step=(w-pad-8)/38;ctx.clearRect(0,0,w,h);m.forEach((row,i)=>row.forEach((v,j)=>{const t=max?v/max:0;ctx.fillStyle=`rgb(${Math.round(10+25*t)},${Math.round(28+131*t)},${Math.round(45+185*t)})`;ctx.fillRect(pad+j*step,pad+i*step,step-.35,step-.35);}));ctx.strokeStyle='#f2c94c';ctx.lineWidth=1.5;ctx.strokeRect(pad,pad+current*step,step*38,step);ctx.fillStyle='#b5c9db';ctx.font='11px sans-serif';for(const i of [0,9,19,29,37]){ctx.textAlign='center';ctx.fillText(String(i+1).padStart(3,'0'),pad+(i+.5)*step,24);ctx.textAlign='right';ctx.fillText(String(i+1).padStart(3,'0'),29,pad+(i+.7)*step);}const cell=event=>{const r=c.getBoundingClientRect(),j=Math.floor((event.clientX-r.left-pad)/step),i=Math.floor((event.clientY-r.top-pad)/step);return i>=0&&i<38&&j>=0&&j<38?{i,j}:null;};c.onpointermove=event=>{const p=cell(event);if(p)$('#attention-tip').textContent=`${D().patients[p.i].id} → ${D().patients[p.j].id}  ${fmt(m[p.i][p.j]*100,5)}%`;};c.onclick=event=>{const p=cell(event);if(p)callback(p.i);};}
