function casewalk(state){const p=pts[state.patient];return `<section class="casewalk"><div class="casewalk-title"><h2>病例演示：从检查到结果核对</h2><span class="badge">当前 ${p.id}</span></div><p>沿着同一位患者，查看真实影像、检查变化、相似病例、指标贡献和实际结局。</p><div class="casewalk-steps">${['单人检查','双人对照','局部SHAP','注意力机制','核对结局'].map((t,j)=>`<button data-case-step="${j}"><span>0${j+1}</span>${t}</button>`).join('')}</div><div class="casewalk-note"><b>当前结果：</b>预测pCR ${pct(p.p)}${state.validation?' · 实际'+(p.label?'pCR':'non-pCR')+' · 阈值0.50下'+((p.p>=.5)===!!p.label?'预测相符':'预测与结局不一致'):' · 实际结局可在第05步显示'}。</div></section>`;}
function close(){step=-1;$('#tourbar').hidden=true;document.body.classList.remove('presenting');if(restore){bridge.set(restore,restore.page);restore=null;}$('#tour').focus();}
function scene(){const s=scenes[step];bridge.set({patient:s.patient??bridge.state().patient,compare:s.compare??null,focus:true,view:'topology',orbit:false,validation:s.validation??false,experiment:s.experiment??'similarity'},s.page,s.preset);document.body.classList.add('presenting');const bar=$('#tourbar');bar.hidden=false;bar.innerHTML=`<div class="show-progress">${scenes.map((_,i)=>`<i class="${i<=step?'done':''}"></i>`).join('')}</div><div class="show-copy"><span>${step+1} / ${scenes.length} · 演示路径</span><h3>${s.title}</h3><p>${s.text}</p></div><div class="tour-controls"><button id="show-prev" ${step===0?'disabled':''}>← 上一幕</button><button id="show-next" class="primary">${step===scenes.length-1?'结束演示':'下一幕 →'}</button><button id="show-full">全屏</button><button id="show-exit">退出</button></div>`;
$('#show-prev').onclick=()=>{step--;scene();};$('#show-next').onclick=()=>{if(step===scenes.length-1)close();else{step++;scene();}};$('#show-exit').onclick=close;$('#show-full').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{bridge.toast('浏览器未允许全屏，可继续演示');}};
requestAnimationFrame(()=>requestAnimationFrame(()=>{if(s.explain)$(`[data-explain-view="${s.explain}"]`)?.click();$(s.target)?.scrollIntoView({block:'start',behavior:'instant'});$('#show-next').focus({preventScroll:true});}));}
function wire(state){document.querySelectorAll('[data-case-step]').forEach(b=>b.onclick=()=>{const j=Number(b.dataset.caseStep),config=j===0?{patient:state.patient,compare:null}:j===1?{patient:pair.a,compare:pair.b}:j===4?{validation:true}:{};bridge.set(config,'patient');requestAnimationFrame(()=>requestAnimationFrame(()=>{if(j===2||j===3)$(`[data-explain-view="${j===2?'local':'flow'}"]`)?.click();$(j===2||j===3?'.explain-section':'.patient-layout')?.scrollIntoView({block:'start',behavior:'instant'});}));});document.querySelectorAll('[data-discovery]').forEach(b=>b.onclick=()=>{const p=picks[Number(b.dataset.discovery)];bridge.set({patient:p.patient,compare:p.compare,focus:true,experiment:p.key==='structure'?'random':'similarity'},p.page);});document.querySelectorAll('[data-review-experiment]').forEach(b=>b.onclick=()=>bridge.set({experiment:b.dataset.reviewExperiment}));document.querySelectorAll('[data-ranked-patient]').forEach(b=>{const choose=()=>bridge.set({patient:Number(b.dataset.rankedPatient),compare:null,focus:true},'patient');b.onclick=choose;b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose();}};});if($('#ranked-validate'))$('#ranked-validate').onclick=()=>bridge.set({validation:!state.validation});}
