(()=>{'use strict';const D=window.RESPGRAPH_DATA,P=D.patients,$=s=>document.querySelector(s);let selected=16,mode='mean';const maxSD=Math.max(...D.robustness.flatMap(r=>r.patient_sd));
function html(){return `<section class="panel section-gap stability-section"><div class="split-head"><div><div class="eyebrow">同一位患者，放进不同的患者组合</div><h2>周围的人换了，她的预测会变多少？</h2><p>每种人数随机抽取100组患者，重新计算预测。下方颜色表示同一位患者在这些组合中的概率波动。</p></div><span class="badge">单位：概率百分点 · SD</span></div><div class="stability-key"><span>颜色越深，预测越稳定</span><i></i><span>越亮，波动越大 · 最高 ${(maxSD*100).toFixed(1)} pp</span></div><div class="stability-layout"><div class="stability-grid"><div class="stability-header"><span>患者</span>${D.robustness.map(r=>`<span>${r.size}人组合</span>`).join('')}</div>${P.map((p,i)=>`<button class="stability-row" data-stable-patient="${i}" aria-pressed="${i===selected}"><span>${p.id}</span>${D.robustness.map(r=>{const sd=r.patient_sd[i],t=sd/maxSD;return `<span style="background:rgb(${Math.round(12+30*t)},${Math.round(32+126*t)},${Math.round(50+178*t)})" title="${p.id} · 在${r.size}人组合中入选${r.patient_counts[i]}次 · 概率标准差${(sd*100).toFixed(3)}个百分点">${(sd*100).toFixed(2)}</span>`;}).join('')}</button>`).join('')}</div><div class="stability-detail" id="stability-detail"></div></div><details><summary>怎样计算概率波动</summary><div class="detail-content">每种队列人数进行100次分层抽样、重新构图和推理。某位患者只有入选时才产生一个结果。热图显示这些结果的标准差（SD）×100，以概率百分点计。所有格子共享同一色标；完整38人结果作为单一参考点。</div></details></section>`;}
function detail(){const p=P[selected],W=570,H=315,L=65,R=24,T=22,B=252,X=v=>L+v*(W-L-R),Y=j=>T+35+j*53;let out='';[0,.25,.5,.75,1].forEach(v=>out+=`<path d="M${X(v)},${T} V${B}" stroke="${v===.5?'#9c9267':'#29465b'}" stroke-dasharray="4 5"/><text x="${X(v)}" y="${B+25}" text-anchor="middle">${v*100}%</text>`);D.robustness.forEach((r,j)=>{const values=r.runs.flatMap(run=>{const at=run.indices.indexOf(selected);return at<0?[]:[run.probabilities[at]];});out+=`<text x="${L-10}" y="${Y(j)+5}" text-anchor="end">${r.size}人</text>`;values.forEach((v,k)=>{const dy=((k%9)-4)*2.4;out+=`<circle cx="${X(v)}" cy="${Y(j)+dy}" r="2.5" fill="#7bcfff" fill-opacity=".55"><title>${r.size}人组合 · ${(v*100).toFixed(2)}%</title></circle>`;});out+=`<path d="M${X(p.p)},${Y(j)-17} V${Y(j)+17}" stroke="#f2994a" stroke-width="2"/>`;});out+=`<text x="${(L+W-R)/2}" y="${H-8}" text-anchor="middle">每个点 = 一次入选后的预测概率</text>`;
return `<div class="eyebrow">点击左侧患者，观察她的实际分布</div><h3>${p.id} · 不同患者组合中的预测</h3><div class="stability-reference"><strong>${(p.p*100).toFixed(1)}%</strong><span>完整38人时的原始概率</span></div><div class="stability-scatter-scroll"><svg viewBox="0 0 ${W} ${H}" class="stability-scatter" role="img" aria-label="${p.id}在四种人数队列实验中的实际概率分布">${out}</svg></div><p class="small">蓝点越集中，预测越稳定；橙线是完整38人队列的结果。</p><div class="stability-selected-stats">${D.robustness.map(r=>`<div><span>${r.size}人组合</span><b>${(r.patient_sd[selected]*100).toFixed(2)} pp</b><small>波动SD · 入选${r.patient_counts[selected]}次</small></div>`).join('')}</div><button data-page="patient" id="stability-patient-link">查看她的检查变化 →</button>`;}
function wire(onSelect){const render=()=>{$('#stability-detail').innerHTML=detail();document.querySelectorAll('[data-stable-patient]').forEach(b=>{b.setAttribute('aria-pressed',Number(b.dataset.stablePatient)===selected);b.onclick=()=>{selected=Number(b.dataset.stablePatient);render();};});$('#stability-patient-link').onclick=()=>onSelect(selected);};render();}
function chartControls(){return `<div class="robustness-controls"><button data-robust-view="mean" aria-pressed="${mode==='mean'}">看均值变化</button><button data-robust-view="spread" aria-pressed="${mode==='spread'}">看重复抽样波动</button></div><div id="robust-reading" class="small muted"></div>`;}
function chart(plot){const all=[...D.robustness.map(r=>r.auc_mean),D.metrics.auc],lo=mode==='mean'?Math.floor((Math.min(...all)-.01)*100)/100:Math.floor((Math.min(...D.robustness.map(r=>r.auc_mean-r.auc_sd))-.01)*100)/100,hi=mode==='mean'?Math.ceil((Math.max(...all)+.01)*100)/100:Math.ceil((Math.max(...D.robustness.map(r=>r.auc_mean+r.auc_sd))+.01)*100)/100;plot('robustness',[{points:D.robustness.map(r=>[r.size,r.auc_mean]),markers:true},{points:[[38,D.metrics.auc]],markers:true,color:'#f2994a'}],{xDomain:[17,40],yDomain:[lo,hi],xTicks:[[19,'19'],[27,'27'],[31,'31'],[35,'35'],[38,'38']],xLabel:'一起参与计算的患者人数',yTicks:mode==='mean'?Array.from({length:Math.round((hi-lo)*100)+1},(_,i)=>lo+i*.01):null,yLabel:mode==='mean'?'平均AUC · 局部放大':'AUC均值 ± 标准差',errors:mode==='spread'?D.robustness.map(r=>({x:r.size,y:r.auc_mean,sd:r.auc_sd})):null});const svg=$('#robustness');svg.dataset.range=JSON.stringify([lo,hi]);$('#robust-reading').textContent=mode==='mean'?`显示AUC ${lo.toFixed(2)}—${hi.toFixed(2)}，便于读取均值变化；切换右侧按钮查看完整波动。`:'蓝色误差棒表示100次抽样结果的标准差；橙点为完整38人队列结果。';document.querySelectorAll('[data-robust-view]').forEach(b=>{b.setAttribute('aria-pressed',b.dataset.robustView===mode);b.onclick=()=>{mode=b.dataset.robustView;chart(plot);};});}
window.RespStability={html,wire,chartControls,chart};})();

