function curve(p,k,comparison=null){const v=p.trajectories[k],cv=comparison?.trajectories[k],values=[...v,...(cv||[])],min=Math.min(0,...values),max=Math.max(0,...values),pad=Math.max(.25,(max-min)*.18),lo=min-pad,hi=max+pad,W=380,H=132,L=42,R=30,T=24,B=101,X=i=>L+i*(W-L-R)/2,Y=n=>B-(n-lo)/(hi-lo)*(B-T);let svg='';for(const n of [...new Set([min,(min+max)/2,max])]){svg+=`<path d="M${L},${Y(n)} H${W-R}" stroke="#284e66" stroke-dasharray="2 5"/><text x="${L-5}" y="${Y(n)+3}" text-anchor="end">${n.toFixed(1)}</text>`;}svg+=`<polyline points="${v.map((n,i)=>`${X(i)},${Y(n)}`).join(' ')}" fill="none" stroke="#77ccff" stroke-width="2.5"/>`;if(cv)svg+=`<polyline points="${cv.map((n,i)=>`${X(i)},${Y(n)}`).join(' ')}" fill="none" stroke="#f6ad65" stroke-width="2" stroke-dasharray="4 3"/>`;v.forEach((n,i)=>{const y=Y(n);svg+=`<circle cx="${X(i)}" cy="${y}" r="3.8" fill="#a5e4ff"/><text x="${X(i)+(i===0?12:0)}" y="${y-12}" text-anchor="${i===0?'start':'middle'}" class="exact-trajectory">${signed(n)}</text><text x="${X(i)}" y="124" text-anchor="middle">T${i}</text>`;});return `<div class="overview-curve"><div><b>${labels[k]}</b><span>ΔT0→T2 <strong>${signed(v[2])}</strong></span></div><svg viewBox="0 0 ${W} ${H}" role="img" data-measured-curve="${k}" aria-label="${p.id} ${labels[k]}，T0 ${signed(v[0])}，T1 ${signed(v[1])}，T2 ${signed(v[2])}">${svg}</svg></div>`;}
