function html(id,comparison=null){if(!manifest?.patients[id])return '';return `<section class="panel imaging-panel" id="patient-imaging" aria-label="患者真实MRI与分割形态"><div class="split-head"><div><div class="eyebrow">SOURCE MRI / SEGMENTATION</div><h2>真实MRI与肿瘤轮廓</h2><p class="small">首次访视 · 浏览MRI切片，并在三维形态中定位切片位置。</p></div><span class="badge">与患者编号联动</span></div><div class="imaging-toolbar"><span>查看</span><button data-mri-patient="${id}" aria-pressed="true">${id}</button>${comparison?`<button data-mri-patient="${comparison}" aria-pressed="false">${comparison}</button>`:''}<label><input id="mri-overlay" type="checkbox" checked> 分割轮廓</label></div>${comparison?`<details class="mri-pair"><summary>并排查看 ${id} 与 ${comparison} 的MRI</summary><div class="mri-pair-grid"><div><canvas id="mri-pair-a" role="img" aria-label="${id}同步浏览MRI"></canvas><div class="mri-canvas-label" id="mri-pair-label-a"></div></div><div><canvas id="mri-pair-b" role="img" aria-label="${comparison}同步浏览MRI"></canvas><div class="mri-canvas-label" id="mri-pair-label-b"></div></div></div><div class="mri-pair-controls"><span>同步相对切片位置</span><input id="mri-pair-range" type="range" min="0" max="100" value="50" aria-label="同步相对切片位置"><button id="mri-pair-lesions">各自定位分割区</button></div></details>`:''}<div class="imaging-grid"><div class="mri-slice-wrap"><canvas id="mri-slice" role="img" aria-label="真实MRI切片与mask叠加"></canvas><div class="mri-canvas-label" id="mri-image-label"></div><div class="mri-slice-controls"><button id="mri-prev" aria-label="上一张切片">−</button><input id="mri-slice-range" type="range" aria-label="MRI切片编号"><button id="mri-next" aria-label="下一张切片">＋</button><output id="mri-slice-number"></output></div><button class="quiet" id="mri-lesion">定位分割区域最大的切片</button></div><div class="mri-surface-wrap"><canvas id="mri-surface" tabindex="0" role="img" aria-label="肿瘤分割区域的三维形态，拖动或方向键旋转，滚轮缩放"></canvas><div class="mri-canvas-label">分割区域 · 三维重建</div><div class="mri-mesh-controls"><span>拖动旋转 · 滚轮缩放</span><button id="mri-reset">复位</button><button id="mri-main" aria-pressed="false">聚焦最大连通区</button><label><input id="mri-plane" type="checkbox" checked> 切片位置</label><label><input id="mri-wire" type="checkbox"> 网格</label></div></div></div><div class="mri-status" id="mri-status" role="status"></div><div class="imaging-caption"><span><i></i>青色轮廓：已有mask标注</span><span>首次访视 · MRI与分割轮廓</span></div></section>`;}
